<script setup lang="ts">import{ref,onUnmounted}from'vue';type Opt={id:number;sku:string;name:string};const props=defineProps<{modelValue:string;productId:number|null}>();const emit=defineEmits<{ 'update:modelValue':[string];'update:productId':[number|null]}>();const options=ref<Opt[]>([]);const open=ref(false);let timer:ReturnType<typeof setTimeout>|undefined;onUnmounted(()=>clearTimeout(timer));const input=(e:Event)=>{const v=(e.target as HTMLInputElement).value;emit('update:modelValue',v);emit('update:productId',null);clearTimeout(timer);timer=setTimeout(async()=>{if(!v.trim()){options.value=[];open.value=false;return}const r=await fetch(`/inventory/product-search?q=${encodeURIComponent(v)}`,{headers:{Accept:'application/json'}});options.value=await r.json();open.value=options.value.length>0},180)};const choose=(o:Opt)=>{emit('update:modelValue',o.sku);emit('update:productId',o.id);options.value=[];open.value=false}</script>
<template><div class="combo"><input :value="props.modelValue" placeholder="输入 SKU 或产品名称" autocomplete="off" @input="input"><ul v-if="open"><li v-for="o in options" :key="o.id" @mousedown.prevent="choose(o)"><strong>{{o.sku}}</strong> — {{o.name}}</li></ul></div></template>
<style scoped>.combo{position:relative}.combo input{width:100%;padding:9px;border:1px solid #dbe2e8;border-radius:8px}.combo ul{position:absolute;z-index:20;top:100%;left:0;right:0;background:white;border:1px solid #dbe2e8;border-radius:8px;max-height:220px;overflow:auto;padding:4px;margin:2px 0;list-style:none}.combo li{padding:8px;cursor:pointer}.combo li:hover{background:#f1f5f9}</style>
